R=Path.cwd();B=R/'verification/sections/466-workspace';D=R/'research/workspace-466';D.mkdir(exist_ok=True)
def read(p):return json.loads((R/p).read_bytes())
def pin(p):
 raw=(R/p).read_bytes();return {'sha256':sha256(raw).hexdigest(),'bytes':len(raw)}
def write(p,value):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n','utf8')
def save(p,text):
 p=R/p;old=p.read_bytes().decode('utf8').splitlines(keepends=True)if p.exists()else[];new=text.splitlines(keepends=True)
 for x,y,k in difflib.SequenceMatcher(None,[v.rstrip('\r\n')for v in old],[v.rstrip('\r\n')for v in new],autojunk=False).get_matching_blocks():new[y:y+k]=old[x:x+k]
 p.write_bytes(''.join(new).encode('utf8'))
